// Récupère le binaire du fichier uploadé via le Form Trigger
const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('Aucun fichier binaire trouvé en entrée.');
}
const binaryKey = binaryKeys[0];
const binaryData = item.binary[binaryKey];

// Décodage du contenu JSON
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const jsonStr = buffer.toString('utf-8');
let spec;
try {
  spec = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('Le fichier fourni n\'est pas un JSON valide: ' + e.message);
}

const id = spec.id;
const name = spec.name;
const description = spec.description || '';
const chars = spec.serviceSpecCharacteristic || [];

// Construction d'un digest compact (une ligne par caractéristique)
// pour alimenter le LLM sans lui envoyer tout le JSON brut.
function formatValue(v) {
  const alias = (v.value && (v.value.alias || v.value.value)) || '';
  const hasRange = v.valueFrom !== null && v.valueFrom !== undefined && v.valueTo !== null && v.valueTo !== undefined;
  if (hasRange) {
    const unit = (v.unitOfMeasure && v.unitOfMeasure !== 'N/A') ? v.unitOfMeasure : '';
    return `${v.valueFrom}-${v.valueTo}${unit} (${alias})`.trim();
  }
  return `${alias}`.trim();
}

const digestLines = chars.map((c) => {
  const vals = (c.serviceSpecCharacteristicValue || []).map(formatValue).filter(Boolean).join(' | ');
  const tags = (c.serviceSpecCharRelationship || [])
    .filter((r) => r.relationshipType === 'tag')
    .map((r) => r.name)
    .join(',');
  return `- ${c.name} [${c.valueType}]${tags ? ' {' + tags + '}' : ''}: ${vals}`;
});

// Limite de sécurité (évite un digest disproportionné pour des specs très longues)
const MAX_LINES = 400;
const digest = digestLines.slice(0, MAX_LINES).join('\n');

return [{
  json: {
    id,
    name,
    description,
    nb_characteristics: chars.length,
    digest
  }
}];

