const llmResponse = $input.first().json;
// Format Ollama /api/chat: { message: { role, content }, done: true, ... }
let resume = (llmResponse.message && llmResponse.message.content) ? llmResponse.message.content.trim() : '';

// Sécurité: certains modèles "thinking" (ex: qwen) peuvent renvoyer des balises <think>...</think>
// avant la réponse finale. On les retire si présentes.
resume = resume.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

if (!resume) {
  throw new Error('Le LLM local n\'a retourné aucun résumé exploitable. Réponse brute: ' + JSON.stringify(llmResponse));
}

const prev = $('2. Extraction & Digest').first().json;

return [{
  json: {
    id: prev.id,
    name: prev.name,
    description: prev.description,
    nb_characteristics: prev.nb_characteristics,
    resume
  }
}];

const embResponse = $input.first().json;
// Format Ollama /api/embeddings: { embedding: [ ... ] }
const vector = embResponse.embedding || null;
if (!vector || !Array.isArray(vector)) {
  throw new Error('Embedding non retourné par Ollama. Réponse brute: ' + JSON.stringify(embResponse));
}

const prev = $('3b. Extraire Résumé').first().json;

// Qdrant accepte un id entier non signé ou un UUID.
// Si l'id source n'est pas un entier valide, on génère un id numérique dérivé (hash).
let pointId = Number(prev.id);
if (!Number.isInteger(pointId) || pointId < 0) {
  let hash = 0;
  const str = String(prev.id);
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
  }
  pointId = hash;
}

// Format attendu par le nœud Qdrant de n8n (LangChain) : { pageContent, metadata }.
// Un payload "à plat" (name, description... à la racine) est renvoyé VIDE par n8n
// ({"pageContent":"","metadata":{}}), d'où l'échec du Grounding sur ces services.
// pageContent reprend le texte embeddé ; metadata porte id/name lus par le pipeline.
const pageContent = [`${prev.name}: ${prev.description || ''}`.trim(), prev.resume || '']
  .filter(Boolean).join(' ').trim();

const point = {
  id: pointId,
  vector: vector,
  payload: {
    pageContent,
    metadata: {
      id: String(prev.id),
      name: prev.name,
      description: prev.description,
      resume: prev.resume,
      nb_characteristics: prev.nb_characteristics
    }
  }
};

return [{ json: { points: [point] } }];

// Vérifie si la collection existe dans Qdrant, la crée sinon (taille de vecteur déduite dynamiquement).
const qdrantBase = 'http://qdrant.example:6333';
const collection = 'generics_CFSS';

const payload = $input.first().json;
const vectorSize = payload.points[0].vector.length;

let exists = true;
try {
  await this.helpers.httpRequest({
    method: 'GET',
    url: `${qdrantBase}/collections/${collection}`,
    json: true
  });
} catch (e) {
  exists = false;
}

if (!exists) {
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `${qdrantBase}/collections/${collection}`,
    json: true,
    body: {
      vectors: {
        size: vectorSize,
        distance: 'Cosine'
      }
    }
  });
}

return [{ json: payload }];
